"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _include_target(line):
    """Return the include path if ``line`` is an ``@include`` directive, else None."""
    parts = line.strip().split(None, 1)
    if not parts or parts[0] != INCLUDE_DIRECTIVE:
        return None
    if len(parts) < 2 or not parts[1].strip():
        raise ConfigError("@include directive requires a path")
    return parts[1].strip()


def _expand(path, stack):
    real = os.path.realpath(path)
    if real in stack:
        chain = " -> ".join(stack + [real])
        raise ConfigError("include cycle detected: {}".format(chain))
    try:
        with open(path, "r", encoding="utf-8") as fh:
            lines = fh.read().splitlines()
    except FileNotFoundError:
        raise ConfigError("included file not found: {}".format(path))

    stack = stack + [real]
    base = os.path.dirname(path)
    expanded = []
    for line in lines:
        target = _include_target(line)
        if target is None:
            expanded.append(line)
            continue
        expanded.extend(_expand(os.path.join(base, target), stack))
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced in place by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    with open(path, "r", encoding="utf-8") as fh:
        lines = fh.read().splitlines()
    real = os.path.realpath(path)
    base = os.path.dirname(path)
    expanded = []
    for line in lines:
        target = _include_target(line)
        if target is None:
            expanded.append(line)
            continue
        expanded.extend(_expand(os.path.join(base, target), [real]))
    return parse_lines(expanded)


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
